python3 - <<'EOF'
import re
from eval_summaries import text_stats  # reuse loader-independent fn? just recompute inline
def load(p):
    return open(p, encoding='utf-8').read().strip()
article=load('article.txt'); g=load('gpt4_answer.txt'); c=load('claude_answer.txt')

def units(t):
    # split on newlines first (bullets/headings), then sentence punctuation
    parts=[]
    for line in t.splitlines():
        line=line.strip().lstrip('*- ')
        for s in re.split(r'(?<=[.!?])\s+', line):
            if s.strip(): parts.append(s.strip())
    return parts

for name,t in [('GPT-4',g),('Claude',c)]:
    words=len(re.findall(r"[A-Za-z0-9$%.\-]+", t))
    us=units(t)
    print(f"{name}: words={words} units={len(us)} avg_words/unit={words/len(us):.1f} "
          f"compression={words/650*100:.1f}% of article ({len(article.split())} words)")
    print('  unit lengths:', [len(re.findall(r"[A-Za-z0-9$%.\-]+",u)) for u in us][:20])
EOF
